// Generates ESM facade entry points for the CJS packages (react, react-dom).
//
// Why this file exists: `export * from "react"` does NOT work. React ships CJS, so
// esbuild emits a runtime __reExport() copy which is not statically analyzable. The
// browser's module linker then throws "does not provide an export named 'useState'"
// at link time. We must enumerate the named exports explicitly, and the only reliable
// way to know them is to require() the package here, at build time, where node exists.
import { createRequire } from "node:module";
import fs from "node:fs";
import { pathToFileURL } from "node:url";
import path from "node:path";

const require = createRequire(import.meta.url);
const IDENT = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
const SKIP = new Set(["default", "__esModule"]);

function namedExportsOf(spec) {
  const mod = require(spec);
  return Object.keys(mod)
    .filter((k) => IDENT.test(k) && !SKIP.has(k))
    .sort();
}

/** A facade that re-exports a CJS module's named exports statically. */
function facadeSource(spec, names) {
  const lines = [
    `// GENERATED by gen-facades.mjs -- do not edit.`,
    `// Static named re-exports of the CJS package "${spec}".`,
    `import __cjs from ${JSON.stringify(spec)};`,
    `export default __cjs;`,
  ];
  if (names.length) {
    // One destructuring statement: esbuild keeps this statically analyzable, so the
    // browser can link `import { useState } from "react"` against it.
    lines.push(`export const {\n  ${names.join(",\n  ")}\n} = __cjs;`);
  }
  return lines.join("\n") + "\n";
}

export function generateFacades(outDir) {
  fs.mkdirSync(outDir, { recursive: true });
  const specs = ["react", "react/jsx-runtime", "react-dom", "react-dom/client"];
  const report = {};
  for (const spec of specs) {
    const names = namedExportsOf(spec);
    const file = path.join(outDir, spec.replace(/[/@]/g, "__") + ".js");
    fs.writeFileSync(file, facadeSource(spec, names));
    report[spec] = { file, count: names.length, names };
  }
  return report;
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const r = generateFacades(path.join(process.cwd(), ".facades"));
  for (const [spec, info] of Object.entries(r)) {
    console.log(`${spec.padEnd(22)} ${String(info.count).padStart(3)} named exports`);
    console.log(`   ${info.names.slice(0, 12).join(", ")}${info.names.length > 12 ? ", ..." : ""}`);
  }
}
